// Generated by build-plugin.mjs from scenes.json: don't edit by hand.
// Builds a "Glass calibration" page of cells, each named glass-<id>.
const SCENES = {"about":"Glass calibration scenes, shared by the Figma plugin and Drawpane's harness. Each cell is a 360 × 240 frame with the same vector backdrop and one glass shape. Settings are Figma's (intensity, refraction and dispersion 0–1; depth and frost in px; angle in degrees).","cell":{"width":360,"height":240,"gap":40,"columns":4},"backdrop":{"gradient":[{"position":0,"color":"#ff7a45"},{"position":0.5,"color":"#ffd166"},{"position":1,"color":"#3d7bf0"}],"rows":{"every":24,"height":6,"colors":["#1c1b1a","#ffffff"],"opacity":0.65},"columns":{"every":30,"width":4,"color":"#0b3d91","opacity":0.55}},"glass":{"x":70,"y":50,"width":220,"height":140,"cornerRadius":36},"defaults":{"lightAngle":-45,"lightIntensity":0.8,"refraction":0.8,"depth":20,"dispersion":0.5,"frost":4},"cells":[{"id":"base"},{"id":"refraction-0","refraction":0},{"id":"refraction-40","refraction":0.4},{"id":"refraction-100","refraction":1},{"id":"depth-5","depth":5},{"id":"depth-40","depth":40},{"id":"depth-80","depth":80},{"id":"dispersion-0","dispersion":0},{"id":"dispersion-100","dispersion":1},{"id":"frost-0","frost":0},{"id":"frost-10","frost":10},{"id":"frost-24","frost":24},{"id":"light-0","lightIntensity":0},{"id":"light-100","lightIntensity":1},{"id":"angle-0","lightAngle":0},{"id":"angle-90","lightAngle":90},{"id":"angle-135","lightAngle":135},{"id":"circle","shape":"ellipse","glass":{"x":110,"y":50,"width":140,"height":140}},{"id":"pill","glass":{"x":50,"y":80,"width":260,"height":80,"cornerRadius":40}},{"id":"square-corners","glass":{"cornerRadius":0}},{"id":"lens-only","lightIntensity":0,"dispersion":0,"frost":0},{"id":"light-only","refraction":0,"dispersion":0,"frost":0,"lightIntensity":1}]};

function rgb(hex) {
  const n = (i) => parseInt(hex.slice(i, i + 2), 16) / 255;
  return { r: n(1), g: n(3), b: n(5) };
}

async function main() {
  const page = figma.createPage();
  page.name = "Glass calibration";
  await figma.setCurrentPageAsync(page);
  const { cell, backdrop, cells, defaults } = SCENES;
  cells.forEach((spec, i) => {
    const settings = { ...defaults, ...spec };
    const glassBox = { ...SCENES.glass, ...(spec.glass || {}) };
    const frame = figma.createFrame();
    frame.name = "glass-" + spec.id;
    frame.resize(cell.width, cell.height);
    frame.x = (i % cell.columns) * (cell.width + cell.gap);
    frame.y = Math.floor(i / cell.columns) * (cell.height + cell.gap);
    frame.clipsContent = true;
    frame.fills = [
      {
        type: "GRADIENT_LINEAR",
        gradientTransform: [
          [1, 0, 0],
          [0, 1, 0],
        ],
        gradientStops: backdrop.gradient.map((s) => ({
          position: s.position,
          color: { ...rgb(s.color), a: 1 },
        })),
      },
    ];
    for (let y = 0, k = 0; y < cell.height; y += backdrop.rows.every, k++) {
      const bar = figma.createRectangle();
      bar.resize(cell.width, backdrop.rows.height);
      bar.x = 0;
      bar.y = y;
      bar.fills = [
        {
          type: "SOLID",
          color: rgb(backdrop.rows.colors[k % backdrop.rows.colors.length]),
          opacity: backdrop.rows.opacity,
        },
      ];
      frame.appendChild(bar);
    }
    for (let x = 0; x < cell.width; x += backdrop.columns.every) {
      const bar = figma.createRectangle();
      bar.resize(backdrop.columns.width, cell.height);
      bar.x = x;
      bar.y = 0;
      bar.fills = [
        { type: "SOLID", color: rgb(backdrop.columns.color), opacity: backdrop.columns.opacity },
      ];
      frame.appendChild(bar);
    }
    const glass = spec.shape === "ellipse" ? figma.createEllipse() : figma.createRectangle();
    glass.name = "glass";
    glass.resize(glassBox.width, glassBox.height);
    glass.x = glassBox.x;
    glass.y = glassBox.y;
    if (spec.shape !== "ellipse") glass.cornerRadius = glassBox.cornerRadius;
    glass.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 }, opacity: 0 }];
    glass.effects = [
      {
        type: "GLASS",
        visible: true,
        lightIntensity: settings.lightIntensity,
        lightAngle: settings.lightAngle,
        refraction: settings.refraction,
        depth: Math.max(1, settings.depth),
        dispersion: settings.dispersion,
        radius: settings.frost,
      },
    ];
    frame.appendChild(glass);
  });
  figma.viewport.scrollAndZoomIntoView(page.children);
  figma.closePlugin("Made " + cells.length + " glass calibration cells.");
}

main().catch((error) => figma.closePlugin("Couldn't make the cells: " + error.message));
